#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int d) : data(d), left(nullptr), right(nullptr) {}
};

Node* insert(Node* node, int value) {
    if (node == nullptr) {
        return new Node(value);
    }
    if (value < node->data) {
        node->left = insert(node->left, value);
    } else {
        node->right = insert(node->right, value);
    }
    return node;
}

int height(Node* node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + max(height(node->left), height(node->right));
}

int balance(Node* node) {
    return height(node->left) - height(node->right);
}

Node* leftRotate(Node* x) {
    Node* y = x->right;
    Node* T = y->left;
    y->left = x;
    x->right = T;
    return y;
}

void preOrder(Node* node) {
    if (node == nullptr) {
        return;
    }
    cout << node->data << " ";
    preOrder(node->left);
    preOrder(node->right);
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    int values[] = {40, 20, 60, 10, 50, 70, 80};
    for (int i = 0; i < 7; i++) {
        root = insert(root, values[i]);
    }
    cout << "Root balance: " << balance(root) << endl;

    Node* parent = root->left;
    Node* leaf = parent->left;
    parent->left = nullptr;
    delete leaf;
    cout << "Root balance after deleting 10: " << balance(root) << endl;
    cout << "Its right child's balance: " << balance(root->right) << endl;

    root = leftRotate(root);
    cout << "Root balance after the rotation: " << balance(root) << endl;
    preOrder(root);
    cout << endl;
    destroy(root);
    return 0;
}
